1	export interface Item {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	}
7	
8	export interface QuoteStep {
9	  op: "quote";
10	  items: Item[];
11	}
12	
13	export interface Damage {
14	  itemType: string;
15	  amount: number;
16	}
17	
18	export interface Incident {
19	  cause: string;
20	  damages: Damage[];
21	}
22	
23	export interface ClaimStep {
24	  op: "claim";
25	  policy: number;
26	  incident: Incident;
27	}
28	
29	export type Step = QuoteStep | ClaimStep;
30	
31	export interface Customer {
32	  yearsWithMHPCO: number;
33	}
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export interface ScenarioOutput {
41	  results: unknown[];
42	}
43	
44	const PROCESSING_FEE = 5;
45	const INITIAL_ASSESSMENT_SURCHARGE_RATE = 0.1;
46	const LOYALTY_YEARS = 2;
47	const LOYALTY_DISCOUNT_RATE = 0.2;
48	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
49	
50	/** The MHPCO insures exactly these item types; anything else is unknown. */
51	interface ItemTypeTerms {
52	  basePremium: number;
53	  insuranceValue: number;
54	}
55	
56	const ITEM_TYPES: Record<string, ItemTypeTerms | undefined> = {
57	  sword: { basePremium: 100, insuranceValue: 1000 },
58	  amulet: { basePremium: 60, insuranceValue: 600 },
59	  staff: { basePremium: 80, insuranceValue: 800 },
60	  potion: { basePremium: 40, insuranceValue: 400 },
61	  rune: { basePremium: 25, insuranceValue: 250 },
62	  moonstone: { basePremium: 25, insuranceValue: 250 },
63	};
64	
65	const termsOfType = (type: string): ItemTypeTerms => {
66	  const terms = ITEM_TYPES[type];
67	  if (terms === undefined) {
68	    throw new Error(`unknown item type: ${type}`);
69	  }
70	  return terms;
71	};
72	
73	const basePremiumOfType = (type: string): number => termsOfType(type).basePremium;
74	
75	const insuranceValueOfType = (type: string): number => termsOfType(type).insuranceValue;
76	
77	const CURSE_SURCHARGE_RATE = 0.5;
78	const HIGH_ENCHANTMENT_LEVEL = 5;
79	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
80	
81	/** An item without an enchantment counts as enchantment 0. */
82	const enchantmentOf = (item: Item): number => item.enchantment ?? 0;
83	
84	const isCursed = (item: Item): boolean => item.cursed === true;
85	const isHighlyEnchanted = (item: Item): boolean =>
86	  enchantmentOf(item) >= HIGH_ENCHANTMENT_LEVEL;
87	
88	/** Item-specific modifiers apply to the base premium of the affected item only. */
89	const itemSurchargesOf = (item: Item): number => {
90	  const basePremium = basePremiumOfType(item.type);
91	  const curseSurcharge = isCursed(item) ? basePremium * CURSE_SURCHARGE_RATE : 0;
92	  const highEnchantmentSurcharge = isHighlyEnchanted(item)
93	    ? basePremium * HIGH_ENCHANTMENT_SURCHARGE_RATE
94	    : 0;
95	  return curseSurcharge + highEnchantmentSurcharge;
96	};
97	
98	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
99	const COMPONENT_BLOCK_SIZE = 3;
100	const COMPONENT_BLOCK_PREMIUM = 60;
101	
102	const isComponent = (type: string): boolean => COMPONENT_TYPES.has(type);
103	
104	/** Tallies anything identified by a type — insured items or damage entries alike. */
105	const countByType = (typed: { type: string }[]): Map<string, number> => {
106	  const counts = new Map<string, number>();
107	  for (const { type } of typed) {
108	    counts.set(type, (counts.get(type) ?? 0) + 1);
109	  }
110	  return counts;
111	};
112	
113	/**
114	 * Items of one type are normally priced individually. The exception is
115	 * components: exactly 3 alike ones form a "building block" priced as a unit.
116	 */
117	const typeGroupPremium = (type: string, count: number): number =>
118	  isComponent(type) && count === COMPONENT_BLOCK_SIZE
119	    ? COMPONENT_BLOCK_PREMIUM
120	    : count * basePremiumOfType(type);
121	
122	const policyBasePremiumOf = (items: Item[]): number =>
123	  [...countByType(items)].reduce(
124	    (sum, [type, count]) => sum + typeGroupPremium(type, count),
125	    0,
126	  );
127	
128	const isLongStanding = (customer: Customer): boolean =>
129	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
130	
131	/** What the policy-wide modifiers are judged against, beyond the items themselves. */
132	interface QuoteContext {
133	  customer: Customer;
134	  isFollowUpContract: boolean;
135	}
136	
137	/**
138	 * Policy-wide modifiers are signed rates charged against the policy base
139	 * premium: surcharges positive, discounts negative.
140	 */
141	const policyModifierRateFor = (context: QuoteContext): number =>
142	  INITIAL_ASSESSMENT_SURCHARGE_RATE -
143	  (isLongStanding(context.customer) ? LOYALTY_DISCOUNT_RATE : 0) -
144	  (context.isFollowUpContract ? FOLLOW_UP_CONTRACT_DISCOUNT_RATE : 0);
145	
146	const itemSurchargesOfPolicy = (items: Item[]): number =>
147	  items.reduce((sum, item) => sum + itemSurchargesOf(item), 0);
148	
149	/** Kept as an exact fraction — only the final premium is rounded. */
150	const premiumBeforeRounding = (items: Item[], context: QuoteContext): number => {
151	  const policyBasePremium = policyBasePremiumOf(items);
152	  const policyModifiers = policyBasePremium * policyModifierRateFor(context);
153	  return policyBasePremium + itemSurchargesOfPolicy(items) + policyModifiers + PROCESSING_FEE;
154	};
155	
156	/** Rounded up, in the MHPCO's favour. */
157	const finalPremiumFor = (items: Item[], context: QuoteContext): number =>
158	  Math.ceil(premiumBeforeRounding(items, context));
159	
160	const DEDUCTIBLE = 100;
161	const CAP_MULTIPLIER = 2;
162	
163	const insuranceSumOf = (items: Item[]): number =>
164	  items.reduce((sum, item) => sum + insuranceValueOfType(item.type), 0);
165	
166	/** A policy created by a quote step, tracked so later claims can draw on it. */
167	interface Policy {
168	  items: Item[];
169	  remainingCap: number;
170	}
171	
172	/** The most a policy will ever pay out, across all claims against it. */
173	const capFor = (items: Item[]): number => insuranceSumOf(items) * CAP_MULTIPLIER;
174	
175	const openPolicyFor = (items: Item[]): Policy => ({ items, remainingCap: capFor(items) });
176	
177	const CLAIM_HIGH_ENCHANTMENT_LEVEL = 8;
178	const CLAIM_HIGH_ENCHANTMENT_RATE = 0.5;
179	
180	/**
181	 * Unrelated to the high-enchantment premium surcharge: that one is judged
182	 * against HIGH_ENCHANTMENT_LEVEL, this one against its own, higher threshold.
183	 */
184	const isHighlyEnchantedForClaims = (insuredItem: Item): boolean =>
185	  enchantmentOf(insuredItem) >= CLAIM_HIGH_ENCHANTMENT_LEVEL;
186	
187	/** The share of the damage the MHPCO reimburses, before the deductible. */
188	const reimbursementRateFor = (insuredItem: Item): number =>
189	  isHighlyEnchantedForClaims(insuredItem) ? CLAIM_HIGH_ENCHANTMENT_RATE : 1;
190	
191	const payoutForDamage = (damage: Damage, insuredItem: Item): number => {
192	  if (damage.amount < 0) {
193	    throw new Error(`damage amount must not be negative: ${String(damage.amount)}`);
194	  }
195	  return damage.amount * reimbursementRateFor(insuredItem) - DEDUCTIBLE;
196	};
197	
198	/**
199	 * The insured item a damage entry draws on. Callers must have cleared the
200	 * damages through rejectDamagesBeyondInsuredCount first, which guarantees a
201	 * match exists; the guard here only discharges that promise for the compiler.
202	 */
203	const insuredItemFor = (damage: Damage, policy: Policy): Item => {
204	  const insuredItem = policy.items.find((item) => item.type === damage.itemType);
205	  if (insuredItem === undefined) {
206	    throw new Error(`claim references uninsured item type ${damage.itemType}`);
207	  }
208	  return insuredItem;
209	};
210	
211	interface Settlement {
212	  payout: number;
213	  remainingCap: number;
214	}
215	
216	/**
217	 * A policy covering N items of a type answers for at most N damage entries of
218	 * it — a second broken sword is not covered by a policy insuring only one.
219	 * This also rejects types the policy does not cover at all (0 insured).
220	 */
221	const rejectDamagesBeyondInsuredCount = (damages: Damage[], policy: Policy): void => {
222	  const insuredCounts = countByType(policy.items);
223	  const damagedCounts = countByType(damages.map(({ itemType }) => ({ type: itemType })));
224	
225	  for (const [type, damaged] of damagedCounts) {
226	    const insured = insuredCounts.get(type) ?? 0;
227	    if (damaged > insured) {
228	      throw new Error(
229	        `claim damages ${String(damaged)} ${type}(s) but only ${String(insured)} insured`,
230	      );
231	    }
232	  }
233	};
234	
235	/**
236	 * Draws against the policy's remaining cap, which it depletes.
237	 * Rounded down, in the MHPCO's favour.
238	 */
239	const settleClaim = (step: ClaimStep, policy: Policy): Settlement => {
240	  rejectDamagesBeyondInsuredCount(step.incident.damages, policy);
241	
242	  const claimed = step.incident.damages.reduce(
243	    (sum, damage) => sum + payoutForDamage(damage, insuredItemFor(damage, policy)),
244	    0,
245	  );
246	  const payout = Math.floor(Math.min(claimed, policy.remainingCap));
247	
248	  policy.remainingCap -= payout;
249	  return { payout, remainingCap: policy.remainingCap };
250	};
251	
252	const policyReferencedBy = (step: ClaimStep, policies: Map<number, Policy>): Policy => {
253	  const policy = policies.get(step.policy);
254	  if (policy === undefined) {
255	    throw new Error(`claim references unknown policy at step ${String(step.policy)}`);
256	  }
257	  return policy;
258	};
259	
260	export const runScenario = (scenario: Scenario): ScenarioOutput => {
261	  const policies = new Map<number, Policy>();
262	
263	  const results = scenario.steps.map((step, stepIndex) => {
264	    if (step.op === "claim") {
265	      return settleClaim(step, policyReferencedBy(step, policies));
266	    }
267	
268	    // Every quote but the first is a follow-up contract for this customer.
269	    const isFollowUpContract = policies.size > 0;
270	    policies.set(stepIndex, openPolicyFor(step.items));
271	
272	    return {
273	      premium: finalPremiumFor(step.items, { customer: scenario.customer, isFollowUpContract }),
274	    };
275	  });
276	
277	  return { results };
278	};
